mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, sys, urllib.request, urllib.error
BASE = "http://localhost:8080"
log = open("/tmp/recon/log.txt", "w")
def L(*a):
    print(*a, file=log, flush=True)
tok = None
def get_token():
    global tok
    while True:
        try:
            req = urllib.request.Request(BASE + "/token", method="POST", data=b"")
            with urllib.request.urlopen(req, timeout=30) as r:
                tok = json.loads(r.read())["token"]; L("token", tok); return
        except urllib.error.HTTPError as e:
            ra = e.headers.get("Retry-After"); L("token err", e.code, ra, e.read()[:200])
            time.sleep(float(ra) if ra else 1)
        except Exception as e:
            L("token exc", repr(e)); time.sleep(1)
def get(path):
    for attempt in range(200):
        if tok is None: get_token()
        req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + tok})
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                body = r.read()
                try:
                    return 200, json.loads(body)
                except Exception as e:
                    L("bad json", path, r.status, body[:300]); time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            body = e.read()[:300]; ra = e.headers.get("Retry-After")
            L("http", e.code, path, "retry-after=", ra, body)
            if e.code == 401: get_token(); continue
            if e.code == 429:
                time.sleep(float(ra) if ra else 1); continue
            if e.code == 404: return 404, body
            time.sleep(float(ra) if ra else 0.5); continue
        except Exception as e:
            L("exc", path, repr(e)); time.sleep(0.5)
    raise SystemExit("gave up on " + path)

pages = {}
path = "/orders?page=1"
while path:
    st, d = get(path)
    assert st == 200, (path, st, d)
    pages[d["page"]] = d
    L("page", d["page"], "of", d["total_pages"], "items", len(d["items"]), "next", d["next"])
    path = d["next"]
json.dump(pages, open("/tmp/recon/pages.json", "w"))
cids = sorted({o["customer_id"] for p in pages.values() for o in p["items"]})
custs = {}
for c in cids:
    st, d = get("/customers/" + c)
    custs[c] = d if st == 200 else {"_status": st, "_body": str(d)}
json.dump(custs, open("/tmp/recon/customers.json", "w"))
print("pages", len(pages), "customers", len(custs))
EOF
cd /tmp/recon && python3 -I fetch.py; tail -5 log.txt; grep -v '^page\|^token' log.txt | awk '{print $1,$2}' | sort | uniq -c

